body.chapterList@js:
cookie.removeCookie(source.getKey());
//java.log(result)
let obj = cache.getFromMemory("lastChapter");
let a = +String(result[result.length - 1].url).match(/(\d+)\.html/)[1];
if (obj) {
	   let b = +String(obj.url).match(/(\d+)\.html/)[1];
	   cache.deleteMemory("lastChapter");
    if (b > a) {
        if (b - a > 1) {
            let arr = [];
            let id = baseUrl.match(/bookId=(\d+)/)[1];
            for (let i = a+1; i < b; i++) {
                arr.push({ name: `第${i}章`, url: `/book/${id}/${i}.html`});
            }
            //java.log(JSON.stringify(arr, null, 2));
            let htm = java.ajax(`https://wechat.idejian.com/catalog?page=${Math.ceil(a / 50)}&bookId=${id}`);
            let e = org.jsoup.Jsoup.parse(htm).select('.catalog_list');      
            arr.forEach(x => {
                let k = e.select(`a[href='${x.url}'] .text`).text() + '';
                if (k) x.name = k;
                result[result.length] = JSON.stringify(x);
            });
        }
        result[result.length] = obj;
    }
}
//java.log(result);
result;

